sys_script_include.script:
var VDIUserLookupUtil = Class.create();
VDIUserLookupUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

getExistingVDI: function() {
    var userId = this.getParameter('sysparm_user_id');
	var result = {
		found: false,
		sys_id: '',
		name: '',
		specs: {}
	};
	if (!userId) {
		return JSON.stringify(result);
	}

	var vdiGr = new GlideRecord('cmdb_ci_virtual_desktop');
	vdiGr.addQuery('assigned_to', userId);
	vdiGr.addQuery('install_status', 1);
	vdiGr.setLimit(1);
	vdiGr.query();

	if(vdiGr.next()){
		result.found = true;
		result.sys_id = vdiGr.getUniqueValue();
		result.name = vdiGr.getValue('u_hostname') || '';
		result.specs = {
			cpu: vdiGr.getValue('u_cpu_core') || '',
			ram: vdiGr.getValue('u_ram_gb') || '',

		};
	}
	return JSON.stringify(result);

    },

    type: 'VDIUserLookupUtil'
});
